using System.Security.Claims;using System.Text;using AuthService.Data;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.AspNetCore.Identity;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;using Microsoft.OpenApi.Models;
namespace AuthService.Extensions;
public static class ServiceCollectionExtensions { public static IServiceCollection AddAuthService(this IServiceCollection s,IConfiguration c){s.AddEndpointsApiExplorer();s.AddSwaggerGen(o=>{o.SwaggerDoc("v1",new OpenApiInfo{Title="WAEC Authentication Service API",Version="v1"});o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Name="Authorization",Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT",In=ParameterLocation.Header});o.AddSecurityRequirement(new OpenApiSecurityRequirement{{new OpenApiSecurityScheme{Reference=new OpenApiReference{Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});s.AddDbContext<AuthDbContext>(o=>o.UseSqlServer(c.GetConnectionString("Auth")??throw new InvalidOperationException("ConnectionStrings:Auth is required.")));s.AddIdentityCore<IdentityUser>(o=>{o.Password.RequiredLength=10;o.Password.RequireDigit=true;o.Password.RequireUppercase=true;o.Password.RequireLowercase=true;o.Password.RequireNonAlphanumeric=true;o.User.RequireUniqueEmail=true;o.Lockout.AllowedForNewUsers=true;o.Lockout.MaxFailedAccessAttempts=5;o.Lockout.DefaultLockoutTimeSpan=TimeSpan.FromMinutes(15);}).AddRoles<IdentityRole>().AddEntityFrameworkStores<AuthDbContext>().AddSignInManager();var jwt=c.GetSection("Jwt");var key=jwt["Key"]??throw new InvalidOperationException("Jwt:Key must be configured.");if(Encoding.UTF8.GetByteCount(key)<32)throw new InvalidOperationException("Jwt:Key must contain at least 32 UTF-8 bytes.");s.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidIssuer=jwt["Issuer"],ValidateAudience=true,ValidAudience=jwt["Audience"],ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),ValidateLifetime=true,ClockSkew=TimeSpan.FromSeconds(30),NameClaimType=ClaimTypes.Name,RoleClaimType=ClaimTypes.Role});s.AddAuthorization(o=>o.AddPolicy("AdminOnly",p=>p.RequireClaim("permission","users.manage")));return s;} }